CREATE TABLE CPF_CACHE_INVALIDATION_VERSION (
    CONSUMER_ID VARCHAR2(180 CHAR) NOT NULL,
    TENANT_ID VARCHAR2(180 CHAR) NOT NULL,
    NAMESPACE_NAME VARCHAR2(180 CHAR) NOT NULL,
    CACHE_KEY_VALUE VARCHAR2(512 CHAR) NOT NULL,
    LAST_VERSION NUMBER(19,0) NOT NULL,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_CPF_CACHE_INV_VERSION PRIMARY KEY (CONSUMER_ID, TENANT_ID, NAMESPACE_NAME, CACHE_KEY_VALUE),
    CONSTRAINT CK_CPF_CACHE_INV_VERSION_NONNEG CHECK (LAST_VERSION >= 0)
);
